    x = observation.get("self", {}).get("x", 0)
    y = observation.get("self", {}).get("y", 0)
    width = observation.get("grid", {}).get("width", 0)
    height = observation.get("grid", {}).get("height", 0)

    # Default move to stay
    dx = 0
    dy = 0

    # Try simple rules that work across modes

    # 1) Resource collection: move toward nearest known resource
    resources = observation.get("resources", [])
    if isinstance(resources, list) and resources:
        # Choose the closest resource within bounds
        best = None
        best_dist = float("inf")
        for r in resources:
            rx = r.get("x", 0)
            ry = r.get("y", 0)
            dist = abs(rx - x) + abs(ry - y)
            if dist < best_dist:
                best_dist = dist
                best = (rx, ry)
        if best is not None:
            rx, ry = best
            dx = 0
            dy = 0
            if rx > x:
                dx = 1
            elif rx < x:
                dx = -1
            if ry > y:
                dy = 1
            elif ry < y:
                dy = -1
            return [dx, dy]

    # 2) Pursuit/Evasion: approach nearest threat or evade nearest threat
    threats = observation.get("threats", [])
    if isinstance(threats, list) and threats:
        best_t = None
        best_dist = float("inf")
        for t in threats:
            tx = t.get("x", 0)
            ty = t.get("y", 0)
            dist = abs(tx - x) + abs(ty - y)
            if dist < best_dist:
                best_dist = dist
                best_t = (tx, ty)
        if best_t is not None:
            tx, ty = best_t
            # If we can pursue (for evading, prefer moving away if near), simple policy:
            dx = 0
            dy = 0
            if tx > x:
                dx = -1
            elif tx < x:
                dx = 1
            if ty > y:
                dy = -1
            elif ty < y:
                dy = 1
            return [dx, dy]

    # 3) Territory control / exploration: move toward center or random-ish bias to center
    center_x = max(0, width // 2)
    center_y = max(0, height // 2)
    if width and height:
        if x < center_x:
            dx = 1
        elif x > center_x:
            dx = -1
        else:
            dx = 0
        if y < center_y:
            dy = 1
        elif y > center_y:
            dy = -1
        else:
            dy = 0
        return [dx, dy]

    # Fallback: stay
    return [0, 0]

